head.script:
scwin.screenId = "jldstf10007";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf10007.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////



///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnSslReturn
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSslReturn = async function () {
    /* sdd-asis-lifecycle:begin fnSslReturn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const fm = (document.frm || { elements: [] });
    const path = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "action_path" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("action_path"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "action_path" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("action_path")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "action_path" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("action_path"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "action_path" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("action_path")))));
    const url = path.split("?");
    const paramAll = url[1].split("&");
    const acptNo = paramAll[0].split("=")[1];
    const gaskScrenID = paramAll[1].split("=")[1];
    const gaccssAuthTpCd = paramAll[2].split("=")[1];
    $c.util.getComponent("ipt_AcptNo").setValue(acptNo);
    $c.util.getComponent("ipt_gAskScrenID").setValue(gaskScrenID);
    $c.util.getComponent("ipt_gAccssAuthTpCd").setValue(gaccssAuthTpCd);
    fm.action = url[0];
    await moveUrl(url[0], {});
    /* sdd-asis-lifecycle:end */
};
